"use client"

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"

import { useComposedRefs } from "@/lib/0nlytype/refs"
import { cn } from "@/lib/utils"

type RowsProps = React.ComponentProps<"ul"> & {
  /**
   * reverse: the row you point at reverses out of ink. ditto: a kind or a
   * year that repeats the row above is set as a ditto mark, and pointing
   * spells it out. trail: a ring before each row that fills with ink once
   * you've been there (the browser's own :visited); where you are is the accent.
   */
  variant?: "reverse" | "ditto" | "trail"
}

/** An index: hairline-separated rows. The one you point at reverses out of ink and steps forward. */
function Rows({ className, variant = "reverse", ref, ...props }: RowsProps) {
  const own = React.useRef<HTMLUListElement>(null)
  const composedRef = useComposedRefs(own, ref)
  // ditto: after every render, mark each kind or year that repeats the one in the row above.
  React.useLayoutEffect(() => {
    if (variant !== "ditto" || !own.current) return
    let above = new Map<string, string>()
    for (const li of own.current.children) {
      const here = new Map<string, string>()
      for (const cell of li.querySelectorAll<HTMLElement>("[data-slot=rows-kind], [data-slot=rows-meta]")) {
        const slot = cell.dataset.slot ?? ""
        const text = cell.textContent?.trim() ?? ""
        cell.toggleAttribute("data-ditto", text !== "" && above.get(slot) === text)
        here.set(slot, text)
      }
      above = here
    }
  })
  return <ul ref={composedRef} data-slot="rows" data-variant={variant === "reverse" ? undefined : variant} className={cn("ot-rows", className)} {...props} />
}

type RowProps = Omit<React.ComponentProps<"li">, "onClick"> & {
  /** Makes the row a link. Without href (or asChild) it is a plain row that doesn't react. */
  href?: string
  /** Render your own link (Next's Link, say) inside the row with the row's look. */
  asChild?: boolean
  /** Pins a state for documentation ("hover", or "visited" for trail); set on the link. */
  "data-force"?: string
  /** Passed to the link. */
  onClick?: React.MouseEventHandler<HTMLElement>
}

/**
 * One row. Give it the parts (RowTitle, RowKind, RowMeta). A row that opens
 * something draws a → on hover; the ink comes in from the side your hand came in
 * and leaves toward the side it goes.
 */
function Row({ href, asChild = false, className, children, onClick, "data-force": force, "aria-current": current, ...props }: RowProps) {
  const Comp = asChild ? Slot : href !== undefined ? "a" : "div"
  const edge = (e: React.PointerEvent<HTMLElement>) => {
    const r = e.currentTarget.getBoundingClientRect()
    e.currentTarget.dataset.edge = e.clientY < r.top + r.height / 2 ? "top" : "bottom"
  }
  return (
    <li data-slot="rows-item" {...props}>
      <Comp
        data-slot="rows-row"
        data-force={force}
        aria-current={current}
        className={cn("ot-rows-link", className)}
        {...(href !== undefined ? { href } : {})}
        onClick={onClick}
        onPointerEnter={edge}
        onPointerLeave={edge}
      >
        {children}
      </Comp>
    </li>
  )
}

function RowTitle({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="rows-title" className={cn("ot-rows-title", className)} {...props} />
}

function RowKind({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="rows-kind" className={cn("ot-rows-kind", className)} {...props} />
}

/** The quiet fact at the end: a year, a count. */
function RowMeta({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="rows-meta" className={cn("ot-rows-meta", className)} {...props} />
}

export { Rows, Row, RowTitle, RowKind, RowMeta, type RowsProps, type RowProps }

@layer components {
  /* ── ot-rows ── an index; the row you point at steps forward.
     Only a row that opens something (an a or a button) reverses and shows the arrow. */
  .ot-rows { list-style: none; margin: 0; padding: 0; border-block-start: var(--ot-hairline) solid var(--ot-rule); }
  .ot-rows > li { border-block-end: var(--ot-hairline) solid var(--ot-rule); }
  .ot-rows-link {
    position: relative; isolation: isolate;
    display: grid; grid-template-columns: minmax(0, 1fr); grid-auto-flow: column; grid-auto-columns: auto;
    align-items: baseline; column-gap: var(--ot-space-6);
    padding-block: var(--ot-space-4); color: inherit; text-decoration: none; --step: 8px;
  }
  /* A row that is a button (a sheet's trigger) spans the row as a link does, and reads from the start. */
  button.ot-rows-link { inline-size: 100%; margin: 0; border: 0; background: none; text-align: start; cursor: pointer; }
  :is([dir="rtl"], [dir="rtl"] *) .ot-rows-link { --step: -8px; }
  .ot-rows-title { font-size: var(--ot-mf); line-height: var(--ot-mf-lh); letter-spacing: var(--ot-mf-tr); font-weight: 300; color: var(--ot-ink); transition: translate var(--ot-moderato) var(--ot-exhale); }
  .ot-rows-kind { color: var(--ot-graphite); }
  .ot-rows-meta { min-inline-size: 4ch; color: var(--ot-pencil); font-variant-numeric: tabular-nums; text-align: end; }
  /* Every row keeps the arrow's column, so a plain row lines up with the rows that open something. */
  .ot-rows-link::after {
    content: "→" / ""; inline-size: 1.2em; justify-self: end; color: var(--ot-ink); opacity: 0; translate: calc(-1 * var(--step)) 0;
    transition: opacity var(--ot-allegro), translate var(--ot-moderato) var(--ot-exhale), color var(--ot-allegro);
  }
  :is([dir="rtl"], [dir="rtl"] *) .ot-rows-link::after { content: "←" / ""; }
  /* The row you point at reverses: ink wipes in from the side your hand came in, the heaviest emphasis there is. */
  .ot-rows:not([data-variant]) .ot-rows-link:is(a[href], button)::before {
    content: ""; position: absolute; inset: 0 calc(-1 * var(--ot-space-3)); z-index: -1;
    background: var(--ot-ink); scale: 1 0; transform-origin: 50% 0;
    transition: scale var(--ot-moderato) var(--ot-exhale);
  }
  .ot-rows-link[data-edge="bottom"]::before { transform-origin: 50% 100%; }
  .ot-rows-link:is(a[href], button) > * { transition: color var(--ot-allegro), translate var(--ot-moderato) var(--ot-exhale), opacity var(--ot-allegro); }
  .ot-rows:not([data-variant]) .ot-rows-link:is(a[href], button):is(:hover, :focus-visible, [data-force~="hover"])::before { scale: 1 1; }
  .ot-rows:not([data-variant]) .ot-rows-link:is(a[href], button):is(:hover, :focus-visible, [data-force~="hover"]) > * { color: var(--ot-paper); }
  .ot-rows-link:is(a[href], button):is(:hover, :focus-visible, [data-force~="hover"])::after { opacity: 1; translate: 0 0; }
  .ot-rows:not([data-variant]) .ot-rows-link:is(a[href], button):is(:hover, :focus-visible, [data-force~="hover"])::after { color: var(--ot-paper); }
  .ot-rows-link:is(a[href], button):is(:hover, :focus-visible, [data-force~="hover"]) .ot-rows-title { translate: var(--step) 0; }
  .ot-rows-link:focus-visible { outline-offset: 4px; }
  /* Narrow, the title takes its own line and the kind and meta sit under it, near it: side by side they would run into each other. */
  @media (max-width: 40rem) {
    .ot-rows-link { grid-auto-flow: row; grid-template-columns: minmax(0, 1fr) auto; column-gap: var(--ot-space-4); row-gap: var(--ot-space-1); }
    .ot-rows-link > .ot-rows-title { grid-column: 1 / -1; }
    .ot-rows-link > .ot-rows-kind { justify-self: start; } /* as wide as its word, so a ditto stands over the word */
    .ot-rows-link::after { display: none; } /* the ink still says which row */
  }

  /* ditto: a kind or a year that repeats the row above is set as a ditto mark, as a ledger or a typed list does, so only what
     changes is written out and the marks set a rhythm down the column. Pointing at a row (or focusing it) spells its dittos out. */
  .ot-rows[data-variant="ditto"] [data-ditto] { position: relative; transition: color var(--ot-allegro); }
  .ot-rows[data-variant="ditto"] :is(.ot-rows-kind, .ot-rows-meta)[data-ditto] { color: transparent; }
  .ot-rows[data-variant="ditto"] [data-ditto]::after {
    content: "\2033" / ""; position: absolute; inset: 0; text-align: center; font-size: 1.3em; line-height: 1.2; color: var(--ot-pencil); transition: opacity var(--ot-allegro);
  }
  .ot-rows[data-variant="ditto"] .ot-rows-link:is(:hover, :focus-visible, [data-force~="hover"]) .ot-rows-kind[data-ditto] { color: var(--ot-graphite); }
  .ot-rows[data-variant="ditto"] .ot-rows-link:is(:hover, :focus-visible, [data-force~="hover"]) .ot-rows-meta[data-ditto] { color: var(--ot-pencil); }
  .ot-rows[data-variant="ditto"] .ot-rows-link:is(:hover, :focus-visible, [data-force~="hover"]) [data-ditto]::after { opacity: 0; }

  @media (forced-colors: active) {
    .ot-rows[data-variant="ditto"] [data-ditto] { forced-color-adjust: none; }
    .ot-rows[data-variant="ditto"] [data-ditto]::after,
    .ot-rows[data-variant="ditto"] .ot-rows-link:is(:hover, :focus-visible, [data-force~="hover"]) :is(.ot-rows-kind, .ot-rows-meta)[data-ditto] { color: CanvasText; }
  }

  /* trail: after the "28 December" calendar, a ring hung in the margin before each row: to come, a hairline ring; been, filled
     with ink (the browser's own :visited, so nothing is stored); here (aria-current), the accent. Pointing inks the ring's line. */
  .ot-rows[data-variant="trail"] .ot-rows-link::before {
    content: ""; position: absolute; inset-inline-start: calc(-1 * var(--ot-space-5)); inset-block-start: calc(var(--ot-space-4) + var(--ot-mf) * 0.62);
    inline-size: var(--ot-space-3); block-size: var(--ot-space-3); margin-block-start: calc(var(--ot-space-3) / -2); box-sizing: border-box; border-radius: 50%;
    border: var(--ot-hairline) solid var(--ot-rule-strong); background-color: var(--ot-paper);
    transition: border-color var(--ot-allegro), scale var(--ot-moderato) var(--ot-spiccato);
  }
  .ot-rows[data-variant="trail"] .ot-rows-link:is(:hover, :focus-visible, [data-force~="hover"])::before { border-color: var(--ot-ink); scale: 1.25; }
  .ot-rows[data-variant="trail"] .ot-rows-link:is(:visited, [data-force~="visited"])::before { border-color: var(--ot-ink); background-color: var(--ot-ink); }
  .ot-rows[data-variant="trail"] .ot-rows-link[aria-current]::before { border-color: var(--ot-accent); background-color: var(--ot-accent); }
  @media (max-width: 40rem) { .ot-rows[data-variant="trail"] .ot-rows-link { padding-inline-start: var(--ot-space-5); } .ot-rows[data-variant="trail"] .ot-rows-link::before { inset-inline-start: 0; } }
  @media (forced-colors: active) {
    .ot-rows[data-variant="trail"] .ot-rows-link::before { forced-color-adjust: none; border-color: CanvasText; background-color: Canvas; }
    .ot-rows[data-variant="trail"] .ot-rows-link:is(:visited, [data-force~="visited"])::before { border-color: VisitedText; background-color: VisitedText; }
    .ot-rows[data-variant="trail"] .ot-rows-link[aria-current]::before { border-color: Highlight; background-color: Highlight; }
  }
}
